//! JSON DTOs shared with the frontend; TypeScript bindings are generated by ts-rs.
//!
//! Addresses, hashes and amounts are strings (lowercase hex / decimal);
//! timestamps are RFC 3339 strings. 64-bit integers are bound as `number`.

use std::collections::{BTreeMap, HashMap};

use chrono::{DateTime, SecondsFormat, Utc};
use eg_core::filter::Edge;
use eg_core::source::{CallKind, Priority, TokenInfo};
use eg_core::types::{Address, Transfer, TransferKind};
use eg_store::{AuditRow, JobRow, LabelRow, SyncRow};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::auth::siwe::SiweFields;
use crate::trust::TrustIndex;

pub fn rfc3339(t: DateTime<Utc>) -> String {
    t.to_rfc3339_opts(SecondsFormat::Millis, true)
}

/// Microsecond precision, matching Postgres `timestamptz`, so a client can echo
/// the value back as an optimistic-concurrency token.
pub fn rfc3339_micros(t: DateTime<Utc>) -> String {
    t.to_rfc3339_opts(SecondsFormat::Micros, true)
}

#[derive(Clone, Debug, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct StatusDto {
    /// The viewer's Etherscan calls today.
    pub quota_used: u32,
    /// The viewer's effective daily limit.
    pub quota_limit: u32,
    /// The viewer's jobs wait for the next reset: the viewer is over their
    /// own quota or the server total is used up.
    pub paused: bool,
    /// The server's daily total is used up (everyone waits).
    pub server_paused: bool,
    /// Next UTC midnight, when the daily quota resets.
    pub reset_at: String,
    pub queue_len: usize,
    /// Current permits per second (lowered during an adaptive slowdown).
    pub rate: f64,
    pub jobs_active: usize,
    /// Provider calls the active jobs still need (upper bound).
    pub queued_calls: u32,
    #[ts(type = "number")]
    pub calls: u64,
    #[ts(type = "number")]
    pub retries: u64,
    #[ts(type = "Record<string, number>")]
    pub errors: BTreeMap<String, u64>,
    /// `"invalid_key"` once Etherscan rejected the API key; null otherwise.
    #[ts(type = r#""invalid_key" | null"#)]
    pub degraded: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct JobDto {
    #[ts(type = "number")]
    pub id: i64,
    pub key: String,
    #[ts(
        type = r#""sync_address" | "fetch_tx" | "contract_meta" | "resolve_names" | "token_meta" | "fetch_block" | "fetch_trace""#
    )]
    pub kind: String,
    #[ts(
        type = r#""pending" | "running" | "paused_quota" | "paused_user_quota" | "done" | "failed" | "cancelled""#
    )]
    pub status: String,
    #[ts(type = r#""interactive" | "background" | "low""#)]
    pub priority: String,
    pub params: serde_json::Value,
    pub progress: Option<serde_json::Value>,
    pub attempts: i32,
    pub error: Option<String>,
    pub created_at: String,
    pub updated_at: String,
    /// Named batches owning the job (batch-less owners are not listed).
    pub batches: Vec<String>,
}

fn priority_str(p: Priority) -> &'static str {
    match p {
        Priority::Interactive => "interactive",
        Priority::Background => "background",
        Priority::Low => "low",
    }
}

impl JobDto {
    pub fn new(j: JobRow, batches: Vec<String>) -> Self {
        Self {
            id: j.id,
            key: j.key,
            kind: j.kind.as_str().to_owned(),
            status: j.status.as_str().to_owned(),
            priority: priority_str(j.priority).to_owned(),
            params: j.params,
            progress: j.progress,
            attempts: j.attempts,
            error: j.error,
            created_at: rfc3339(j.created_at),
            updated_at: rfc3339(j.updated_at),
            batches,
        }
    }
}

